import React from 'react';

import { addWorkoutPhotoAsync } from '@apps/Workouts/@services/workoutsPhoto.service';
import { IWorkoutPhotoAddDTO } from '@apps/Workouts/@types/DTO/workouts.dto.types';
import { IWorkoutPhotoFull } from '@apps/Workouts/@types/workouts.types';
import { getInputDate } from '@helpers/dateHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohImageUploader from '@ui-kit/ImageUploader';

interface IWorkoutPhotoAddFormProps {
  id_workout: number;
  callback: (newPhoto: IWorkoutPhotoFull) => void;
}

const WorkoutPhotoAddForm: React.FC<IWorkoutPhotoAddFormProps> = ({ id_workout, callback }) => {
  const [url, setUrl] = React.useState<string | undefined>(undefined);
  return (
    <div style={{ overflowY: 'auto', maxHeight: 320 }}>
      <PohImageUploader
        folder={`images/workouts/${id_workout}`}
        name={`workout_${id_workout}`}
        src={url}
        width={800}
        height={600}
        sizes={[255, 800]}
        validation={{ maxHeight: 7777, maxWidth: 5555, size: 10024288 }}
        includeExif
        onChange={async (src, res, exif) => {
          setUrl(src ?? undefined);
          const data: IWorkoutPhotoAddDTO = {
            id_workout,
            is_main: '1',
            lat: 0,
            lon: 0,
            altitude: 0,
            url_preview: '',
            url: '',
            date: getInputDate(new Date()),
            comment: '',
          };

          const exifDate =
            exif?.['DateTimeOriginal']?.description ?? exif?.['DateCreated']?.description;
          const exifLatitude = exif?.['GPSLatitude']?.description;
          const exifLongitude = exif?.['GPSLongitude']?.description;
          const exifAltitude = exif?.['GPSAltitude']?.description;
          const exifMake = exif?.['Make']?.description;
          const exifModel = exif?.['Model']?.description;

          type T = Pick<
            IWorkoutPhotoAddDTO,
            'url' | 'url_preview' | 'comment' | 'date' | 'lat' | 'lon' | 'altitude'
          >;
          const handleInputChange = (field: keyof T) => (value: string) => {
            Object.assign(data, { [field]: value });
          };

          if (exifDate && exifDate.length) {
            try {
              const exifDateStr = exifDate.replace(
                /^(\d\d\d\d)\D(\d\d?)\D(\d\d?)\D(\d\d)\D(\d\d?)/,
                '$1-$2-$3T$4:$5',
              );
              const ddd = new Date(exifDateStr);
              handleInputChange('date')(getInputDate(ddd));
            } catch (error) {
              console.warn(`Failed to get Exif Date: ${exifDate}`, error);
            }
          }

          if (exifLatitude) {
            handleInputChange('lat')(exifLatitude.toString());
          }

          if (exifLongitude) {
            handleInputChange('lon')(exifLongitude.toString());
          }

          if (exifAltitude) {
            handleInputChange('altitude')(parseInt(exifAltitude).toString());
          }

          if (exifMake && exifMake.length) {
            handleInputChange('comment')(`${data.comment} ${exifMake} ${exifModel}`);
          }

          handleInputChange('url')(src ?? '');
          handleInputChange('url_preview')(res?.sizes?.[255] ?? src ?? '');

          if (!src?.length) return notificationHelper.warn('need image');
          try {
            const { id } = await addWorkoutPhotoAsync(data);
            callback({
              id,
              is_main: data.is_main == '1',
              url_preview: data.url,
              url: data.url_preview,
              date: new Date(data.date),
              comment: data.comment,
              created: {
                date: new Date(),
                user: {
                  id: 0,
                  name: 'X',
                  surname: 'X',
                  photo: '',
                },
              },
              coordinates: null,
            });

            notificationHelper.success('Добавлено');
          } finally {
            setUrl(undefined);
          }
        }}
      />
    </div>
  );
};

export default WorkoutPhotoAddForm;
