import React from 'react';

import { getWorkoutTagsAsync } from '@apps/Workouts/@services/workoutsTags.service';
import { IWorkoutTag } from '@apps/Workouts/@types/workouts.types';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import { showModal } from '@ui-kit/Modal';

interface ISelectWorkoutTagModalProps {
  onSelect(sel: IWorkoutTag): void;
  excludeIds?: number[];
}

const SelectWorkoutTagModal: React.FC<ISelectWorkoutTagModalProps> = ({ onSelect, excludeIds }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [tags, setTags] = React.useState<IWorkoutTag[]>([]);

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        const fetchedTags = await getWorkoutTagsAsync();
        setTags(fetchedTags.filter((x) => !excludeIds?.length || !excludeIds?.includes(x.id)));
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [excludeIds]);

  if (isLoading) {
    return (
      <div className="d-flex align-items-center justify-content-center">
        <PohLoader />
      </div>
    );
  }

  if (err) {
    return (
      <div className="d-flex align-items-center justify-content-center">
        <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>
      </div>
    );
  }

  if (tags.length === 0) {
    return <Empty>Нет доступных тегов</Empty>;
  }
  return (
    <div style={{ overflowY: 'auto', maxHeight: 400 }}>
      <PohList
        data={tags.map((t) => ({
          key: t.id,
          content: t.name,
          action: true,
          onClick: () => onSelect(t),
        }))}
      />
    </div>
  );
};

export const selectWorkoutTagAsync = (excludeIds?: number[]): Promise<IWorkoutTag> => {
  return new Promise((res) => {
    showModal({
      title: 'Выбор тега',
      style: { width: 400 },
      children: (close) => (
        <SelectWorkoutTagModal
          excludeIds={excludeIds}
          onSelect={(s) => {
            res(s);
            close();
          }}
        />
      ),
    });
  });
};
